PDF_DIR, EMAIL_DIR = seedmod.PDF_DIR, seedmod.EMAIL_DIR
HIDDEN_PDFS = {"white_text": "poisoned_white_text.pdf", "tiny_font": "poisoned_tiny_font.pdf",
               "off_page": "poisoned_off_page.pdf", "zero_width": "poisoned_zero_width.pdf"}


@pytest.fixture(scope="module")
def world(tmp_path_factory, seed_template):
    from tests.conftest import copy_seeded

    engine = create_engine(f"sqlite:///{copy_seeded(seed_template, tmp_path_factory.mktemp('assets'))}")
    s = Session(engine)
    summary = seed_template[1]
    yield s, summary
    s.close()


def fp_of(path: Path) -> str:
    return layout.fingerprint(path.read_bytes())


def scan_pdf(path: Path):
    return injection.scan(ScanItem(kind="pdf", pdf_bytes=path.read_bytes()))


# ---------------------------------------------------------------- layouts


def test_every_vendor_has_one_consistent_layout_and_they_differ(world):
    s, summary = world
    by_vendor = defaultdict(set)
    for inv in s.exec(select(Invoice).where(Invoice.pdf_path.is_not(None))).all():
        if inv.id.startswith("inv_atk"):
            continue
        by_vendor[inv.vendor_id].add(fp_of(BACKEND / inv.pdf_path))
    assert len(by_vendor) == 30
    assert all(len(fps) == 1 for fps in by_vendor.values())  # same vendor, same layout, every invoice
    assert len({next(iter(f)) for f in by_vendor.values()}) >= 29  # different vendors look different


def test_forged_invoices_use_a_different_layout_but_the_poisoned_one_copies_it(world):
    s, _ = world
    real = {v: fp_of(BACKEND / s.get(Invoice, i).pdf_path) for v, i in
            (("ven_summit", seedmod_sample(s, "ven_summit")), ("ven_northside", seedmod_sample(s, "ven_northside")),
             ("ven_keystone", seedmod_sample(s, "ven_keystone")))}
    bank = fp_of(PDF_DIR / "inv_atk_bank_change.pdf")
    ceo = fp_of(PDF_DIR / "inv_atk_ceo_pressure.pdf")
    assert bank != real["ven_summit"] and ceo != real["ven_northside"] and bank != ceo
    assert fp_of(PDF_DIR / "inv_atk_poisoned_pdf.pdf") == real["ven_keystone"]  # hidden text does not change the layout
    for key, technique in (("alder", "white_text"), ("bayview", "tiny_font"), ("granite", "off_page"), ("tidewater", "zero_width")):
        assert fp_of(PDF_DIR / HIDDEN_PDFS[technique]) == fp_of(BACKEND / s.get(Invoice, seedmod_sample(s, f"ven_{key}")).pdf_path), technique


def seedmod_sample(s, vendor_id):
    return s.exec(select(Invoice.id).where(Invoice.vendor_id == vendor_id, Invoice.pdf_path.is_not(None), ~Invoice.id.like("inv_atk%"))).first()


def test_layout_changed_signal_uses_the_fingerprint(world):
    s, _ = world
    payment, ctx = build_context(s, s.get(Invoice, "inv_atk_bank_change"))
    assert ctx.layout_changed is True
    assert any(sig.name == "invoice_format_changed" for sig in risk.assess(payment, ctx).signals)
    payment, ctx = build_context(s, s.get(Invoice, "inv_atk_poisoned_pdf"))
    assert ctx.layout_changed is False
    assert layout.layout_changed(b"x", set()) is False  # no past layouts, nothing to compare


def test_layouts_vary_in_the_ways_a_person_would_notice():
    lays = [seedmod.layout_for(v.key, v.trade) for v in seedmod.VENDORS]
    assert len({l.font for l in lays}) == 3 and len({l.columns for l in lays}) > 8
    assert len({l.number_label for l in lays}) == 3 and len({l.footer for l in lays}) >= 4
    assert len({l.logo_style for l in lays}) == 3


# ---------------------------------------------------------------- samples and extraction


def test_at_least_20_historical_samples_extract_correctly(world, monkeypatch, tmp_path):
    s, summary = world
    monkeypatch.setattr(extract, "get_settings", lambda: Settings(mock_claude=True, extract_cache_dir=str(tmp_path)))
    assert len(summary.sample_invoice_ids) >= 20
    for inv_id in summary.sample_invoice_ids:
        inv = s.get(Invoice, inv_id)
        ex = extract.extract_pdf((BACKEND / inv.pdf_path).read_bytes())
        assert ex.vendor_name == s.get(Vendor, inv.vendor_id).name, inv_id
        assert (ex.invoice_number, ex.amount_usd, ex.due_date) == (inv.number, inv.amount_usd, inv.due_date), inv_id
        assert ex.remittance.routing_hash == inv.remittance_json["routing_hash"], inv_id
        assert ex.remittance.account_last4 == inv.remittance_json["account_last4"], inv_id
        assert ex.remittance.bank_name == inv.remittance_json["bank_name"], inv_id


def test_samples_cover_all_vendors_and_bank_changes(world):
    s, summary = world
    vendors = {s.get(Invoice, i).vendor_id for i in summary.sample_invoice_ids}
    assert len(vendors) == 30
    for key in seedmod.BANK_CHANGES:  # the newest sample carries the post-change account
        inv = s.get(Invoice, max(i for i in summary.sample_invoice_ids if s.get(Invoice, i).vendor_id == f"ven_{key}"))
        cur = s.exec(select(VendorBankAccount).where(VendorBankAccount.vendor_id == f"ven_{key}", VendorBankAccount.valid_to.is_(None))).one()
        assert inv.remittance_json["account_last4"] == cur.account_last4


def test_clean_pdfs_never_trip_the_scanner(world):
    s, summary = world
    clean = [BACKEND / s.get(Invoice, i).pdf_path for i in summary.sample_invoice_ids] + \
            [BACKEND / s.get(Invoice, i).pdf_path for i in summary.clean_invoice_ids]
    assert len(clean) >= 70
    for path in clean:
        assert scan_pdf(path) == [], path.name


# ---------------------------------------------------------------- poisoned PDFs


@pytest.mark.parametrize("technique, filename", HIDDEN_PDFS.items())
def test_poisoned_pdf_is_caught_with_its_own_technique(technique, filename):
    findings = scan_pdf(PDF_DIR / filename)
    assert [f.technique for f in findings] == [technique]
    f = findings[0]
    assert f.confidence >= 0.9
    assert "AI assistant" in f.snippet and "remittance" in f.snippet and "approve" in f.snippet


@pytest.mark.parametrize("technique, filename", HIDDEN_PDFS.items())
def test_poisoned_pdf_forces_the_hidden_instruction_hard_rule(technique, filename):
    v = Vendor(name="V", trade="t", email_domain="v.com", created_at=seedmod.ANCHOR.replace(year=2020))
    ctx = risk.RiskContext(vendor=v, requested_destination=None, last_verified_destination=None, prior_payment_count=9,
                           history_amounts=[100.0, 110.0, 105.0], injection_findings=scan_pdf(PDF_DIR / filename), now=seedmod.ANCHOR)
    from app.models import Payment
    a = risk.assess(Payment(run_id="r", invoice_id="i", amount_usd=105.0), ctx)
    assert a.hard_rules_fired == ["hidden_instructions"] and a.decision == Decision.hold


def test_each_poisoned_pdf_really_hides_its_text():
    import io

    import pdfplumber

    def chars(name):
        with pdfplumber.open(io.BytesIO((PDF_DIR / name).read_bytes())) as pdf:
            return pdf.pages[0], pdf.pages[0].chars

    page, cs = chars("poisoned_white_text.pdf")
    assert any(c["non_stroking_color"] in ((1, 1, 1), (1,), 1, [1, 1, 1]) or tuple(c["non_stroking_color"] or ()) == (1, 1, 1) for c in cs)
    page, cs = chars("poisoned_tiny_font.pdf")
    assert min(c["size"] for c in cs) < 2
    page, cs = chars("poisoned_off_page.pdf")
    assert any(c["x0"] > page.width for c in cs)
    page, cs = chars("poisoned_zero_width.pdf")
    zw = [c for c in cs if c["text"] in "​‌‍"]
    assert len(zw) > 500 and len({round(c["x0"], 1) for c in zw}) == 1  # real zero-width characters with zero advance
    # and the sentence around them still reads normally
    text = page.extract_text().replace("​", "").replace("‌", "").replace("‍", "")
    assert "AI assistant" not in text


def test_zero_width_pdf_still_extracts_as_a_normal_invoice(monkeypatch, tmp_path):
    monkeypatch.setattr(extract, "get_settings", lambda: Settings(mock_claude=True, extract_cache_dir=str(tmp_path)))
    ex = extract.extract_pdf((PDF_DIR / "poisoned_zero_width.pdf").read_bytes())
    assert ex.vendor_name == "Tidewater Drywall Supply" and ex.invoice_number == "TID-9001"


def test_planted_poisoned_invoice_hides_white_text():
    assert [f.technique for f in scan_pdf(PDF_DIR / "inv_atk_poisoned_pdf.pdf")] == ["white_text"]


# ---------------------------------------------------------------- poisoned HTML emails


@pytest.mark.parametrize(
    "name, technique",
    [("poisoned_html_comment.html", "html_comment"), ("poisoned_display_none.html", "hidden_element"), ("poisoned_same_color.html", "same_color_text")],
)
def test_poisoned_html_email_is_caught(name, technique):
    html = (EMAIL_DIR / name).read_text()
    findings = injection.scan(ScanItem(kind="email", text=html))
    assert [f.technique for f in findings] == [technique]
    assert findings[0].confidence >= 0.9 and "AI assistant" in findings[0].snippet
    from app.services.ingest import plain_text

    visible = plain_text(re.sub(r"<!--.*?-->", "", html, flags=re.S))
    assert "Attached is invoice" in visible


def test_clean_html_email_is_not_flagged():
    html = '<html><body style="background:#f7f7f7"><p style="color:#222222">Invoice attached.</p><span style="color:#ff0000">Overdue</span></body></html>'
    assert injection.scan(ScanItem(kind="email", text=html)) == []


# ---------------------------------------------------------------- attack cards


def cards_from_markdown():
    text = (BACKEND.parent / "demo" / "attack-cards.md").read_text()
    return [json.loads(b) for b in re.findall(r"```json\n(.*?)\n```", text, flags=re.S)]


def test_attack_cards_use_the_api_shape_and_exist_in_the_seed(world):
    s, summary = world
    cards = cards_from_markdown()
    names = [c["card"] for c in cards]
    assert {"classic_bank_change", "poisoned_invoice", "ceo_pressure"} <= set(names)
    assert names.count("freestyle") >= 3
    threads = set(s.exec(select(Message.thread_id)).all())
    for c in cards:
        assert set(c) == {"attacker_name", "card", "payload"}
        p = c["payload"]
        assert {"thread_id", "from_addr", "body"} <= set(p) and p["thread_id"] in threads, c["card"]
        assert re.fullmatch(r"[A-Za-z0-9_-]{1,64}", p["thread_id"])
    poisoned = next(c for c in cards if c["card"] == "poisoned_invoice")
    assert (PDF_DIR / poisoned["payload"]["pdf"]).exists()


def test_cards_markdown_is_regenerated_from_the_seed(world):
    _, summary = world
    assert (BACKEND.parent / "demo" / "attack-cards.md").read_text() == attack_cards.render(attack_cards.build_cards(summary))


def test_attack_cards_are_caught(world):
    s, _ = world
    cards = {c["card"] + str(i): c for i, c in enumerate(cards_from_markdown())}
    for c in cards.values():
        p = c["payload"]
        vendor_id = s.exec(select(Message.vendor_id).where(Message.thread_id == p["thread_id"])).first()
        cur = s.exec(select(VendorBankAccount).where(VendorBankAccount.vendor_id == vendor_id, VendorBankAccount.valid_to.is_(None))).one()
        pdf = p.get("pdf")
        moves_money = pdf is None and "Routing number:" in p["body"]
        remit = {"routing_hash": "f" * 64, "account_last4": "6213", "bank_name": "Harborline Bank"} if moves_money else \
                {"routing_hash": cur.routing_hash, "account_last4": cur.account_last4, "bank_name": cur.bank_name}
        msg = Message(thread_id=p["thread_id"], vendor_id=vendor_id, from_addr=p["from_addr"], reply_to=p.get("reply_to"),
                      subject=p.get("subject", "s"), body=p["body"], received_at=seedmod.ANCHOR, is_attack=True)
        inv = Invoice(vendor_id=vendor_id, message_id=msg.id, number="X-1", amount_usd=148900.0 if "148,900" in p["body"] else 5000.0,
                      due_date=seedmod.CURRENT_RUN, remittance_json=remit,
                      pdf_path=f"seed/invoices/{pdf}" if pdf else None)
        s.add_all([msg, inv])
        s.commit()
        payment, ctx = build_context(s, inv)
        a = risk.assess(payment, ctx)
        assert a.decision != Decision.auto_pay and a.hard_rules_fired, (c["card"], p["from_addr"], a.reasons)
        if c["card"] in ("classic_bank_change", "ceo_pressure"):
            assert a.decision == Decision.hold_and_verify
        if pdf or "<html" in p["body"]:
            assert "hidden_instructions" in a.hard_rules_fired


def test_every_vendor_has_three_or_more_pdfs_in_one_layout(world):
    s, summary = world
    per_vendor = defaultdict(list)
    for inv in s.exec(select(Invoice).where(Invoice.pdf_path.is_not(None), ~Invoice.id.like("inv_atk%"), Invoice.number != "X-1")).all():  # X-1: rows an earlier card test added
        per_vendor[inv.vendor_id].append(fp_of(BACKEND / inv.pdf_path))
    assert len(per_vendor) == 30
    for vid, fps in per_vendor.items():
        assert len(fps) >= 3 and len(set(fps)) == 1, vid  # at least the 3 history PDFs, all in one layout
    paid = set(s.exec(select(Payment.invoice_id)).all())
    for v in seedmod.VENDORS:  # the three history PDFs are the vendor's LAST three paid invoices
        mine = s.exec(select(Invoice).where(Invoice.vendor_id == f"ven_{v.key}", Invoice.id.in_(paid)).order_by(Invoice.id)).all()
        assert all(i.pdf_path for i in mine[-3:]) and sum(1 for i in mine if i.pdf_path) == 3, v.key
